create table advance_payments (amount number(14,2) not null, payment_date date not null, created_at timestamp(6), id number(19,0) generated as identity, project_id number(19,0), tenant_id raw(16) not null, advance_number varchar2(50 char) not null unique, payment_from varchar2(200 char) not null, description CLOB, status varchar2(255 char) not null check (status in ('RECEIVED','SETTLED')), primary key (id));
